// OWNER: slicer/printer agent. SQLite catalog: a rebuildable index over the project folders
// (folders + git are the source of truth). Everything here can be regenerated by rebuildIndex().
//
// Print records are the one thing that originates in the app rather than in a project file, so each
// one is also written to <project>/.studio/prints/<id>.json; rebuildIndex() reads them back.
import Database from "better-sqlite3"
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync, renameSync } from "node:fs"
import { join } from "node:path"
import { randomUUID } from "node:crypto"
import { PROJECTS_DIR, STUDIO_HOME } from "../config"
import { displayUrl } from "../cad/display"
import type {
  AgentEvent,
  CalibrationScope,
  CatalogProject,
  CatalogSession,
  CatalogSort,
  CheckSeverity,
  PrintJobState,
  PrintOutcome,
  PrintRecord,
  PrintResult,
  Project,
} from "../../shared/types"

type DB = Database.Database

export const DB_PATH = () => join(STUDIO_HOME, "index.sqlite")
const ID_RE = /^[a-z0-9][a-z0-9-]*$/

// ---------------------------------------------------------------------------------------------
// Schema + migrations (PRAGMA user_version)
// ---------------------------------------------------------------------------------------------

const MIGRATIONS: string[] = [
  // v1
  `
  CREATE TABLE projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    path TEXT NOT NULL,
    tags TEXT NOT NULL DEFAULT '[]',          -- json array
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    thumbnail_path TEXT,                       -- relative to project root
    source TEXT,                               -- json or null
    license TEXT
  );
  CREATE TABLE parts (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    id TEXT NOT NULL,
    file TEXT NOT NULL,
    qty INTEGER NOT NULL DEFAULT 1,
    colors TEXT NOT NULL DEFAULT '[]',
    last_check_summary TEXT,
    last_rendered_at TEXT,
    PRIMARY KEY (project_id, id)
  );
  CREATE TABLE sessions (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL DEFAULT '',
    forked_from TEXT,
    created_at TEXT,
    last_message_at TEXT,
    cost_usd REAL NOT NULL DEFAULT 0,
    message_count INTEGER NOT NULL DEFAULT 0,
    first_prompt TEXT
  );
  CREATE INDEX sessions_project ON sessions(project_id);
  CREATE TABLE prints (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,                  -- no FK: keep the log even if a project is removed
    part_ids TEXT NOT NULL DEFAULT '[]',
    gcode_name TEXT NOT NULL,
    printer_filename TEXT,
    started_at TEXT NOT NULL,
    finished_at TEXT,
    state TEXT NOT NULL,                       -- printing | complete | cancelled | error
    result TEXT,                               -- user-reported: success | failed
    notes TEXT,
    estimated_time_s REAL,
    filament_g REAL
  );
  CREATE INDEX prints_project ON prints(project_id, started_at);
  CREATE VIRTUAL TABLE search USING fts5(project_id UNINDEXED, name, tags, parts, sessions, tokenize = 'unicode61 remove_diacritics 2');
  `,
  // v2: Machines (printer farms): which machine a print ran on.
  `
  ALTER TABLE prints ADD COLUMN machine_id TEXT;
  CREATE INDEX prints_machine ON prints(machine_id, started_at);
  `,
  // v3: what the printer said when a print ended (e.g. an early cancel).
  `
  ALTER TABLE prints ADD COLUMN printer_message TEXT;
  `,
  // v4 (R15): the job it printed, how long it really took, its calibration scope and the user's structured outcome.
  `
  ALTER TABLE prints ADD COLUMN job_id TEXT;
  ALTER TABLE prints ADD COLUMN actual_duration_s REAL;
  ALTER TABLE prints ADD COLUMN scope TEXT;                 -- json CalibrationScope
  ALTER TABLE prints ADD COLUMN outcome TEXT;               -- json PrintOutcome
  `,
]

function migrate(db: DB) {
  const v = db.pragma("user_version", { simple: true }) as number
  for (let i = v; i < MIGRATIONS.length; i++) {
    db.transaction(() => {
      db.exec(MIGRATIONS[i])
      db.pragma(`user_version = ${i + 1}`)
    })()
  }
}

let db: DB | null = null
let dbPath: string | null = null

/** Open (and migrate) the index. If the file was missing or empty, it is rebuilt from the folders. */
export function getDb(): DB {
  const path = DB_PATH()
  if (db && dbPath === path) return db
  mkdirSync(STUDIO_HOME, { recursive: true })
  const fresh = !existsSync(path) || statSync(path).size === 0
  const d = new Database(path)
  d.pragma("journal_mode = WAL")
  d.pragma("foreign_keys = ON")
  d.pragma("busy_timeout = 3000")
  migrate(d)
  db = d
  dbPath = path
  if (fresh) rebuildIndex()
  return d
}

export function closeDb() {
  db?.close()
  db = null
  dbPath = null
}

// ---------------------------------------------------------------------------------------------
// Helpers reading derived info from the project folder
// ---------------------------------------------------------------------------------------------

const projectRoot = (id: string) => join(PROJECTS_DIR, id)
const mtimeIso = (f: string) => (existsSync(f) ? statSync(f).mtime.toISOString() : null)
const readJson = <T>(f: string): T | null => {
  try {
    return JSON.parse(readFileSync(f, "utf8")) as T
  } catch {
    return null
  }
}
const parseArr = (s: string | null): string[] => {
  try {
    const v = JSON.parse(s ?? "[]")
    return Array.isArray(v) ? v : []
  } catch {
    return []
  }
}

export interface ProjectExtras {
  updatedAt?: string
  thumbnailPath?: string | null
  license?: string | null
}

function deriveExtras(p: Project): Required<ProjectExtras> {
  const root = projectRoot(p.id)
  let mtime = 0
  for (const f of [join(root, "project.json"), ...p.parts.map((pt) => join(root, pt.file))]) {
    if (existsSync(f)) mtime = Math.max(mtime, statSync(f).mtimeMs)
  }
  const first = p.parts[0]
  const thumb = first ? `renders/${first.id}-iso.png` : null
  let license: string | null = null
  if (p.source?.importId) {
    const src = readJson<{ license?: unknown }>(join(root, "imports", p.source.importId, "source.json"))
    if (src?.license) license = typeof src.license === "string" ? src.license : JSON.stringify(src.license)
  }
  return {
    updatedAt: new Date(mtime || Date.now()).toISOString(),
    thumbnailPath: thumb && existsSync(join(root, thumb)) ? thumb : null,
    license,
  }
}

// ---------------------------------------------------------------------------------------------
// Writes
// ---------------------------------------------------------------------------------------------

/** Index a project (from its project.json contents). Missing extras are derived from the folder. */
export function upsertProject(p: Project, extras: ProjectExtras = {}) {
  const d = getDb()
  const x = { ...deriveExtras(p), ...extras }
  const root = projectRoot(p.id)
  d.transaction(() => {
    d.prepare(
      `INSERT INTO projects (id, name, path, tags, created_at, updated_at, thumbnail_path, source, license)
       VALUES (@id, @name, @path, @tags, @created_at, @updated_at, @thumbnail_path, @source, @license)
       ON CONFLICT(id) DO UPDATE SET name=excluded.name, path=excluded.path, tags=excluded.tags,
         created_at=excluded.created_at, updated_at=excluded.updated_at, thumbnail_path=excluded.thumbnail_path,
         source=excluded.source, license=excluded.license`,
    ).run({
      id: p.id,
      name: p.name,
      path: root,
      tags: JSON.stringify(p.tags ?? []),
      created_at: p.createdAt,
      updated_at: x.updatedAt,
      thumbnail_path: x.thumbnailPath,
      source: p.source ? JSON.stringify(p.source) : null,
      license: x.license,
    })
    d.prepare(`DELETE FROM parts WHERE project_id = ?`).run(p.id)
    const ins = d.prepare(
      `INSERT INTO parts (project_id, id, file, qty, colors, last_check_summary, last_rendered_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
    )
    for (const pt of p.parts) {
      const check = readJson<{ summary?: CheckSeverity }>(join(root, ".studio", "checks", `${pt.id}.json`))
      ins.run(p.id, pt.id, pt.file, pt.qty ?? 1, JSON.stringify(pt.colors ?? []), check?.summary ?? null, mtimeIso(join(root, "renders", `${pt.id}-iso.png`)))
    }
    // Sessions listed in project.json (titles/forks); transcript stats come from upsertSession/touchSession.
    for (const s of p.sessions ?? []) {
      d.prepare(
        `INSERT INTO sessions (id, project_id, title, forked_from) VALUES (?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET title=excluded.title, forked_from=excluded.forked_from, project_id=excluded.project_id`,
      ).run(s.id, p.id, s.title ?? "", s.forkedFrom ?? null)
    }
    refreshSearch(d, p.id)
  })()
}

/** Remove a project from the index (prints are kept: they are a log). */
export function removeProject(projectId: string) {
  const d = getDb()
  d.transaction(() => {
    d.prepare(`DELETE FROM projects WHERE id = ?`).run(projectId)
    d.prepare(`DELETE FROM search WHERE project_id = ?`).run(projectId)
  })()
}

export interface SessionPatch {
  title?: string
  forkedFrom?: string | null
  createdAt?: string | null
  lastMessageAt?: string | null
  costUsd?: number
  messageCount?: number
  firstPrompt?: string | null
}

/** Insert/replace a session row. Fields not given keep their current values. */
export function upsertSession(projectId: string, sessionId: string, patch: SessionPatch = {}) {
  const d = getDb()
  if (!d.prepare(`SELECT 1 FROM projects WHERE id = ?`).get(projectId)) return
  d.transaction(() => {
    d.prepare(`INSERT INTO sessions (id, project_id) VALUES (?, ?) ON CONFLICT(id) DO NOTHING`).run(sessionId, projectId)
    const cols: Record<keyof SessionPatch, string> = {
      title: "title",
      forkedFrom: "forked_from",
      createdAt: "created_at",
      lastMessageAt: "last_message_at",
      costUsd: "cost_usd",
      messageCount: "message_count",
      firstPrompt: "first_prompt",
    }
    const sets: string[] = []
    const vals: unknown[] = []
    for (const [k, col] of Object.entries(cols) as [keyof SessionPatch, string][]) {
      if (patch[k] !== undefined) {
        sets.push(`${col} = ?`)
        vals.push(patch[k])
      }
    }
    if (sets.length) d.prepare(`UPDATE sessions SET ${sets.join(", ")} WHERE id = ?`).run(...vals, sessionId)
    if (patch.title !== undefined || patch.firstPrompt !== undefined) refreshSearch(d, projectId)
  })()
}

/**
 * Cheap per-message update from the agent service. Increments message_count, sets last_message_at,
 * and fills created_at / first_prompt if they are still empty.
 */
export function touchSession(
  projectId: string,
  sessionId: string,
  t: { lastMessageAt?: string; costUsd?: number; userPrompt?: string; title?: string } = {},
) {
  const d = getDb()
  if (!d.prepare(`SELECT 1 FROM projects WHERE id = ?`).get(projectId)) return
  const at = t.lastMessageAt ?? new Date().toISOString()
  d.transaction(() => {
    d.prepare(`INSERT INTO sessions (id, project_id) VALUES (?, ?) ON CONFLICT(id) DO NOTHING`).run(sessionId, projectId)
    d.prepare(
      `UPDATE sessions SET message_count = message_count + 1, last_message_at = ?,
         created_at = COALESCE(created_at, ?),
         cost_usd = COALESCE(?, cost_usd),
         first_prompt = COALESCE(first_prompt, ?),
         title = COALESCE(?, title)
       WHERE id = ?`,
    ).run(at, at, t.costUsd ?? null, t.userPrompt ?? null, t.title ?? null, sessionId)
    if (t.userPrompt || t.title) refreshSearch(d, projectId)
  })()
}

function refreshSearch(d: DB, projectId: string) {
  d.prepare(`DELETE FROM search WHERE project_id = ?`).run(projectId)
  const p = d.prepare(`SELECT name, tags FROM projects WHERE id = ?`).get(projectId) as { name: string; tags: string } | undefined
  if (!p) return
  const parts = (d.prepare(`SELECT id FROM parts WHERE project_id = ?`).all(projectId) as { id: string }[]).map((r) => r.id)
  const sess = d.prepare(`SELECT title, first_prompt FROM sessions WHERE project_id = ?`).all(projectId) as {
    title: string
    first_prompt: string | null
  }[]
  d.prepare(`INSERT INTO search (project_id, name, tags, parts, sessions) VALUES (?, ?, ?, ?, ?)`).run(
    projectId,
    p.name,
    parseArr(p.tags).join(" "),
    // ids like "cable-clip" -> also searchable as "cable clip"
    parts.map((id) => `${id} ${id.replace(/[-_]+/g, " ")}`).join(" "),
    sess.map((s) => `${s.title} ${s.first_prompt ?? ""}`).join("\n"),
  )
}

// ---------------------------------------------------------------------------------------------
// Prints (also persisted to <project>/.studio/prints/<id>.json)
// ---------------------------------------------------------------------------------------------

interface PrintRow {
  id: string
  project_id: string
  part_ids: string
  gcode_name: string
  printer_filename: string | null
  machine_id: string | null
  printer_message: string | null
  started_at: string
  finished_at: string | null
  state: string
  result: string | null
  notes: string | null
  estimated_time_s: number | null
  filament_g: number | null
  job_id: string | null
  actual_duration_s: number | null
  scope: string | null
  outcome: string | null
}
const parseObj = <T>(s: string | null): T | null => {
  if (!s) return null
  try {
    return JSON.parse(s) as T
  } catch {
    return null
  }
}
const toPrint = (r: PrintRow): PrintRecord => ({
  id: r.id,
  projectId: r.project_id,
  machineId: r.machine_id ?? null,
  printerMessage: r.printer_message ?? null,
  partIds: parseArr(r.part_ids),
  gcodeName: r.gcode_name,
  printerFilename: r.printer_filename,
  startedAt: r.started_at,
  finishedAt: r.finished_at,
  state: r.state as PrintJobState,
  result: (r.result as PrintResult) ?? null,
  notes: r.notes,
  estimatedTimeS: r.estimated_time_s,
  filamentG: r.filament_g,
  jobId: r.job_id ?? null,
  actualDurationS: r.actual_duration_s ?? null,
  scope: parseObj<CalibrationScope>(r.scope),
  outcome: parseObj<PrintOutcome>(r.outcome),
})

function writePrintRow(d: DB, rec: PrintRecord) {
  d.prepare(
    `INSERT OR REPLACE INTO prints (id, project_id, part_ids, gcode_name, printer_filename, started_at, finished_at,
       state, result, notes, estimated_time_s, filament_g, machine_id, printer_message, job_id, actual_duration_s, scope, outcome)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    rec.id,
    rec.projectId,
    JSON.stringify(rec.partIds),
    rec.gcodeName,
    rec.printerFilename,
    rec.startedAt,
    rec.finishedAt,
    rec.state,
    rec.result,
    rec.notes,
    rec.estimatedTimeS,
    rec.filamentG,
    rec.machineId ?? null,
    rec.printerMessage ?? null,
    rec.jobId ?? null,
    rec.actualDurationS ?? null,
    rec.scope ? JSON.stringify(rec.scope) : null,
    rec.outcome ? JSON.stringify(rec.outcome) : null,
  )
}

function persistPrint(rec: PrintRecord) {
  if (!ID_RE.test(rec.projectId)) return
  const root = projectRoot(rec.projectId)
  if (!existsSync(root)) return
  const dir = join(root, ".studio", "prints")
  mkdirSync(dir, { recursive: true })
  const f = join(dir, `${rec.id}.json`)
  writeFileSync(f + ".tmp", JSON.stringify(rec, null, 2) + "\n")
  renameSync(f + ".tmp", f)
}

export function getPrint(id: string): PrintRecord | null {
  const r = getDb().prepare(`SELECT * FROM prints WHERE id = ?`).get(id) as PrintRow | undefined
  return r ? toPrint(r) : null
}

export function recordPrintStart(
  rec: Omit<PrintRecord, "id" | "startedAt" | "finishedAt" | "state" | "result" | "notes"> & { startedAt?: string },
): PrintRecord {
  const full: PrintRecord = {
    ...rec,
    id: randomUUID(),
    startedAt: rec.startedAt ?? new Date().toISOString(),
    finishedAt: null,
    state: "printing",
    result: null,
    notes: null,
  }
  writePrintRow(getDb(), full)
  persistPrint(full)
  return full
}

/** Mark a print finished (state from the printer, plus what it said). No-op (returns null) if already finished. */
export function recordPrintFinish(
  id: string,
  state: Exclude<PrintJobState, "printing">,
  finishedAt = new Date().toISOString(),
  printerMessage: string | null = null,
) {
  const cur = getPrint(id)
  if (!cur || cur.finishedAt) return null
  const ran = (Date.parse(finishedAt) - Date.parse(cur.startedAt)) / 1000
  const next: PrintRecord = {
    ...cur,
    state,
    finishedAt,
    printerMessage: printerMessage ?? cur.printerMessage ?? null,
    actualDurationS: isFinite(ran) && ran > 0 ? Math.round(ran) : null,
  }
  writePrintRow(getDb(), next)
  persistPrint(next)
  return next
}

/** Store the structured outcome (R15); result/notes mirror it for older readers. */
export function setPrintOutcome(id: string, outcome: PrintOutcome | null) {
  const cur = getPrint(id)
  if (!cur) return null
  const next: PrintRecord = {
    ...cur,
    outcome,
    ...(outcome ? { result: outcome.rating === "failed" ? "failed" : "success", notes: outcome.notes } : {}),
  }
  writePrintRow(getDb(), next)
  persistPrint(next)
  return next
}

/** User-reported outcome after a print ("success"/"failed" + notes). */
export function setPrintResult(id: string, patch: { result?: PrintResult; notes?: string | null }) {
  const cur = getPrint(id)
  if (!cur) return null
  const next: PrintRecord = {
    ...cur,
    result: patch.result !== undefined ? patch.result : cur.result,
    notes: patch.notes !== undefined ? patch.notes : cur.notes,
  }
  writePrintRow(getDb(), next)
  persistPrint(next)
  return next
}

export function openPrints(): PrintRecord[] {
  return (getDb().prepare(`SELECT * FROM prints WHERE finished_at IS NULL ORDER BY started_at`).all() as PrintRow[]).map(toPrint)
}

export function listPrints(projectId?: string, limit = 200, machineId?: string): PrintRecord[] {
  const where: string[] = []
  const args: unknown[] = []
  if (projectId) {
    where.push("project_id = ?")
    args.push(projectId)
  }
  if (machineId) {
    where.push("machine_id = ?")
    args.push(machineId)
  }
  const rows = getDb()
    .prepare(`SELECT * FROM prints ${where.length ? "WHERE " + where.join(" AND ") : ""} ORDER BY started_at DESC LIMIT ?`)
    .all(...args, limit)
  return (rows as PrintRow[]).map(toPrint)
}

// ---------------------------------------------------------------------------------------------
// Queries
// ---------------------------------------------------------------------------------------------

/** Turn free text into a safe FTS5 query: every word must match as a prefix. */
export function ftsQuery(q: string): string | null {
  const words = q
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean)
    .slice(0, 12)
  return words.length ? words.map((w) => `"${w}"*`).join(" AND ") : null
}

export interface CatalogQuery {
  query?: string
  tag?: string
  sort?: CatalogSort
  limit?: number
}

export function listCatalog(opts: CatalogQuery = {}): CatalogProject[] {
  const d = getDb()
  const where: string[] = []
  const args: unknown[] = []
  const fts = opts.query ? ftsQuery(opts.query) : null
  if (opts.query && !fts) return []
  if (fts) {
    where.push(`p.id IN (SELECT project_id FROM search WHERE search MATCH ?)`)
    args.push(fts)
  }
  if (opts.tag) {
    where.push(`EXISTS (SELECT 1 FROM json_each(p.tags) WHERE lower(json_each.value) = lower(?))`)
    args.push(opts.tag)
  }
  const order = {
    updated: "p.updated_at DESC",
    created: "p.created_at DESC",
    name: "p.name COLLATE NOCASE ASC",
    printed: "lp_started IS NULL, lp_started DESC, p.updated_at DESC",
  }[opts.sort ?? "updated"]
  const rows = d
    .prepare(
      `SELECT p.*,
         (SELECT count(*) FROM parts WHERE project_id = p.id) AS part_count,
         (SELECT count(*) FROM sessions WHERE project_id = p.id) AS session_count,
         lp.id AS lp_id, lp.state AS lp_state, lp.result AS lp_result, lp.started_at AS lp_started, lp.finished_at AS lp_finished
       FROM projects p
       LEFT JOIN prints lp ON lp.id = (SELECT id FROM prints WHERE project_id = p.id ORDER BY started_at DESC LIMIT 1)
       ${where.length ? "WHERE " + where.join(" AND ") : ""}
       ORDER BY ${order}
       LIMIT ?`,
    )
    .all(...args, opts.limit ?? 500) as (Record<string, unknown> & { id: string })[]
  return rows.map((r) => {
    const thumb = r.thumbnail_path as string | null
    const thumbAbs = thumb ? join(projectRoot(r.id), thumb) : null
    const thumbOk = thumbAbs && existsSync(thumbAbs)
    return {
      id: r.id,
      name: r.name as string,
      tags: parseArr(r.tags as string),
      createdAt: r.created_at as string,
      updatedAt: r.updated_at as string,
      thumbnailUrl: thumbOk ? displayUrl(r.id, thumb!, Math.round(statSync(thumbAbs!).mtimeMs)) : null,
      license: (r.license as string) ?? null,
      source: r.source ? JSON.parse(r.source as string) : null,
      partCount: r.part_count as number,
      sessionCount: r.session_count as number,
      lastPrint: r.lp_id
        ? {
            id: r.lp_id as string,
            state: r.lp_state as PrintJobState,
            result: (r.lp_result as PrintResult) ?? null,
            startedAt: r.lp_started as string,
            finishedAt: (r.lp_finished as string) ?? null,
          }
        : null,
    }
  })
}

export function listTags(): { tag: string; count: number }[] {
  return getDb()
    .prepare(
      `SELECT json_each.value AS tag, count(*) AS count FROM projects, json_each(projects.tags)
       GROUP BY lower(json_each.value) ORDER BY count DESC, tag COLLATE NOCASE`,
    )
    .all() as { tag: string; count: number }[]
}

export function listSessions(projectId: string): CatalogSession[] {
  const rows = getDb()
    .prepare(`SELECT * FROM sessions WHERE project_id = ? ORDER BY COALESCE(last_message_at, created_at) DESC`)
    .all(projectId) as Record<string, unknown>[]
  return rows.map((r) => ({
    id: r.id as string,
    projectId: r.project_id as string,
    title: (r.title as string) || (r.first_prompt as string | null)?.slice(0, 60) || "Untitled session",
    forkedFrom: (r.forked_from as string) ?? null,
    createdAt: (r.created_at as string) ?? null,
    lastMessageAt: (r.last_message_at as string) ?? null,
    costUsd: r.cost_usd as number,
    messageCount: r.message_count as number,
    firstPrompt: (r.first_prompt as string) ?? null,
  }))
}

// ---------------------------------------------------------------------------------------------
// Rebuild from folders
// ---------------------------------------------------------------------------------------------

/**
 * Read a session transcript (.studio/sessions/<id>.jsonl) into catalog stats. Lines are normalized agent events
 * (R11a) or, in older transcripts, raw runtime messages; a resumed old session has both.
 */
export function scanTranscript(file: string): SessionPatch {
  const out: SessionPatch = { messageCount: 0, costUsd: 0, createdAt: null, lastMessageAt: null, firstPrompt: null }
  let text: string
  try {
    text = readFileSync(file, "utf8")
  } catch {
    return out
  }
  const cost = (c: unknown) => {
    if (typeof c === "number" && isFinite(c)) out.costUsd = Math.max(out.costUsd ?? 0, c)
  }
  for (const line of text.split("\n")) {
    if (!line.trim()) continue
    let env: { ts?: string; schemaVersion?: number; event?: AgentEvent; message?: { type?: string; text?: string; total_cost_usd?: number; studio_cost_usd?: number } }
    try {
      env = JSON.parse(line)
    } catch {
      continue // torn last line
    }
    out.messageCount!++
    if (env.ts) {
      out.createdAt ??= env.ts
      out.lastMessageAt = env.ts
    }
    const ev = env.schemaVersion ? env.event : undefined
    if (ev) {
      if (ev.type === "run.started" && typeof ev.input?.text === "string" && !out.firstPrompt) out.firstPrompt = ev.input.text.slice(0, 2000)
      const usage = ev.type === "usage.updated" ? ev.usage : ev.type === "run.completed" || ev.type === "run.failed" || ev.type === "run.interrupted" ? ev.result?.usage : null
      if (usage?.final) cost(usage.billedUsd ?? usage.estimatedApiUsd)
      continue
    }
    const m = env.message
    if (m?.type === "user_input" && typeof m.text === "string" && !out.firstPrompt) out.firstPrompt = m.text.slice(0, 2000)
    // studio_cost_usd = the agent's cumulative session cost (survives resumes); older transcripts only have total_cost_usd
    if (m?.type === "result") cost(typeof m.studio_cost_usd === "number" ? m.studio_cost_usd : m.total_cost_usd)
  }
  return out
}

/** Drop everything and repopulate from PROJECTS_DIR. Returns counts. */
export function rebuildIndex(): { projects: number; sessions: number; prints: number } {
  const d = getDb()
  const counts = { projects: 0, sessions: 0, prints: 0 }
  d.transaction(() => {
    d.exec(`DELETE FROM search; DELETE FROM parts; DELETE FROM sessions; DELETE FROM projects; DELETE FROM prints;`)
    if (!existsSync(PROJECTS_DIR)) return
    for (const id of readdirSync(PROJECTS_DIR).sort()) {
      if (!ID_RE.test(id)) continue
      const root = projectRoot(id)
      const p = readJson<Project>(join(root, "project.json"))
      if (!p || p.id !== id) continue
      // Sessions (titles, forks) live in .studio/state.json, outside git; project.json is the fallback.
      const st = readJson<Pick<Project, "sessions" | "activeSessionId">>(join(root, ".studio", "state.json"))
      if (Array.isArray(st?.sessions)) p.sessions = st.sessions
      p.parts ??= []
      p.sessions ??= []
      p.tags ??= []
      upsertProject(p)
      counts.projects++
      const sdir = join(root, ".studio", "sessions")
      if (existsSync(sdir)) {
        for (const f of readdirSync(sdir)) {
          if (!f.endsWith(".jsonl")) continue
          upsertSession(id, f.slice(0, -".jsonl".length), scanTranscript(join(sdir, f)))
          counts.sessions++
        }
      }
      const pdir = join(root, ".studio", "prints")
      if (existsSync(pdir)) {
        for (const f of readdirSync(pdir)) {
          if (!f.endsWith(".json")) continue
          const rec = readJson<PrintRecord>(join(pdir, f))
          if (!rec?.id || !rec.startedAt) continue
          writePrintRow(d, { ...rec, projectId: id })
          counts.prints++
        }
      }
      refreshSearch(d, id)
    }
  })()
  return counts
}
